// RULE (Steve 10/11/2026): requests from the bot's advance questionnaire carry city + full name; they are added to the email to the company. Do not remove.
const HM=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const DAYS=['ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת'];
const SLOTS={8:'08:00-10:00',10:'10:00-12:00',12:'12:00-14:00',14:'14:00-16:00',16:'16:00-18:00',18:'18:00-20:00'};
const arrj=v=>{ if(typeof v==='string'){ try{return JSON.parse(v);}catch(e){return [];} } return Array.isArray(v)?v:[]; };
const dg2=s=>String(s==null?'':s).replace(/\D/g,'');
const s9=dg2(input.sender).slice(-9);
let repName='';
for(const r of arrj(input.targets)){ if(r&&s9.length===9&&dg2(r[1]).slice(-9)===s9) repName=String(r[0]||'').replace(/\s+/g,' ').trim(); }
const MG={'544604246':'סטיב (מנהל)','504445169':'ירדן בן שלוש (מנהל)','525102820':'טלי (מנהלת)','525192071':'הילה (מנהלת)','584896222':'קורל (מנהלת)'};
if(MG[s9]) repName=MG[s9];
function nowIL(){return new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));}
function pad(n){return String(n).padStart(2,'0');}
function pickStart(a,b){if(a<8)a+=12;if(b<8)b+=12;if(b<a&&SLOTS[b])return b;return SLOTS[a]?a:null;}
function parseDateSlot(t,now){
  let d=null,slot=null,m;
  const today=new Date(now.getFullYear(),now.getMonth(),now.getDate());
  m=t.match(/(\d{1,2})\s*[./]\s*(\d{1,2})(?:\s*[./]\s*(\d{2,4}))?/);
  if(m){
    const day=+m[1],mon=+m[2];let y=m[3]?(+m[3]<100?2000+ +m[3]:+m[3]):today.getFullYear();
    if(mon>=1&&mon<=12&&day>=1&&day<=31){d=new Date(y,mon-1,day); if(!m[3]&&d<today)d=new Date(y+1,mon-1,day);}
    t=t.replace(m[0],' ');
  } else if(/מחרתיים/.test(t)){d=new Date(today);d.setDate(d.getDate()+2);t=t.replace(/מחרתיים/,' ');}
  else if(/מחר/.test(t)){d=new Date(today);d.setDate(d.getDate()+1);t=t.replace(/מחר/,' ');}
  else if(/היום/.test(t)){d=new Date(today);t=t.replace(/היום/,' ');}
  else { const wm=t.match(/(?:ב?יום\s*|ל)?(ראשון|שני|שלישי|רביעי|חמישי|שישי)(?![א-ת])/); if(wm){ const idx=['ראשון','שני','שלישי','רביעי','חמישי','שישי'].indexOf(wm[1]); let diff=(idx-today.getDay()+7)%7; if(diff===0)diff=7; d=new Date(today); d.setDate(d.getDate()+diff); t=t.replace(wm[0],' '); } }
  m=t.match(/(\d{1,2})(?::\d{2})?\s*(?:-|–|—|עד|ל-?)\s*(\d{1,2})(?::\d{2})?/);
  if(m){const s=pickStart(+m[1],+m[2]); if(s)slot=s; t=t.replace(m[0],' ');}
  else { m=t.match(/(?:ב?שעה|מ-?)\s*(\d{1,2})(?::\d{2})?/); if(m){let s=+m[1]; if(s<8)s+=12; if(s%2)s-=1; if(SLOTS[s])slot=s; t=t.replace(m[0],' ');} }
  return {d,slot,rest:t};
}
function fmt(d,slot){
  if(!d)return {};
  const o={full_date:'יום '+DAYS[d.getDay()]+' '+d.getDate()+' '+HM[d.getMonth()]+' '+d.getFullYear(),
    iso_date:d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate()),
    short_date:d.getDate()+'/'+(d.getMonth()+1)};
  if(slot){o.slot=SLOTS[slot];o.short_slot=slot+'-'+(slot+2);}
  return o;
}
const now=nowIL();
const raw=String(input.text||'');
let t=' '+raw.replace(/הקדמה|להקדים|תקדים|בבקשה|תודה/g,' ')+' ';
let phone=null,num=null,name=null,m;
m=t.match(/(?:\+?972[-\s]?|0)(5\d)[-\s]?(\d{3})[-\s]?(\d{4})/);
if(m){phone=m[1]+m[2]+m[3];t=t.replace(m[0],' ');}
else{m=t.match(/(?:\+?972[-\s]?|0)([2-489])[-\s]?(\d{7})(?!\d)/);if(m){phone=m[1]+m[2];t=t.replace(m[0],' ');}}
m=t.match(/(?<![\d/.])\d{6,9}(?![\d/.])/);
if(m){num=m[0].replace(/^0+/,'');t=t.replace(m[0],' ');}
const allRe=/כל\s*(?:שעות\s*)?ה?יום|לא\s*משנה(?:\s*לו|\s*לה|\s*לי)?(?:\s*ה?שעה)?|כל\s*שעה|גמיש|מתי\s*ש(?:נוח|יהיה|אפשר)/;
const allDay=allRe.test(t);
t=t.replace(new RegExp(allRe.source,'g'),' ');
const ds=parseDateSlot(t,now);t=ds.rest;
const starts=[];if(ds.slot)starts.push(ds.slot);
{const re=/(\d{1,2})(?::\d{2})?\s*(?:-|–|—|עד|ל-?)\s*(\d{1,2})(?::\d{2})?/g;let mm;while((mm=re.exec(t))){const s0=pickStart(+mm[1],+mm[2]);if(s0&&!starts.includes(s0))starts.push(s0);}t=t.replace(re,' ');}
starts.sort((a,b)=>a-b);
let slotText=null,shortSlot=null,emailSlot=null;
if(allDay||[8,10,12,14,16].every(x=>starts.includes(x))){slotText='כל היום';shortSlot='כל היום';emailSlot='כל היום';}
else if(starts.length===1){slotText=SLOTS[starts[0]];shortSlot=starts[0]+'-'+(starts[0]+2);emailSlot='שעות '+shortSlot;}
else if(starts.length>1){slotText=starts.map(x=>SLOTS[x]).join(' / ');shortSlot=starts.map(x=>x+'-'+(x+2)).join(' / ');emailSlot='שעות '+starts.map(x=>x+'-'+(x+2)).join(' או ');}
const today0=new Date(now.getFullYear(),now.getMonth(),now.getDate());
const sameDay=ds.d&&ds.d.getTime()===today0.getTime();
const stop=new Set(['ל','לתאריך','תאריך','בתאריך','בשעות','שעות','שעה','בין','את','הלקוח','לקוח','של','ביום','יום','ו','עם','מספר','טלפון','תז','ת.ז','ת"ז','נייד','ללקוח','ה','לשעות','ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת','בוקר','צהריים','רוצה','התקנה','אתה','יכול','לשלוח','בקשה','לו','לה','השעה']);
const words=t.replace(/[^֐-׿a-zA-Z'"\s]/g,' ').split(/\s+/).filter(w=>w&&!stop.has(w)&&w.length>1);
if(words.length)name=words.join(' ');
const errors=[];
if(!phone&&!num&&!name)errors.push('לא זיהיתי את הלקוח (טלפון / ת"ז / שם)');
if(!ds.d)errors.push('לא זיהיתי תאריך (למשל 1/10 או יום ראשון)');
if(ds.d&&ds.d.getDay()===6)errors.push('התאריך שביקשת יוצא בשבת');
if(!slotText)errors.push('לא זיהיתי חלון שעות (08-10, 10-12, 12-14, 14-16, 16-18, 18-20, או לא משנה השעה)');
const titles=(input.titles||[]).map(x=>String((x.properties||x).title||x));
const want=[0,-1,1].map(k=>{const dd=new Date(now.getFullYear(),now.getMonth()+k,1);return HM[dd.getMonth()]+' '+dd.getFullYear();});
if(ds.d){const w=HM[ds.d.getMonth()]+' '+ds.d.getFullYear(); if(!want.includes(w))want.push(w);}
const tabs=[];for(const w of want){const f=titles.find(x=>x.trim()===w);if(f&&!tabs.includes(f))tabs.push(f);}
if(!tabs.length)errors.push('לא מצאתי לשונית של החודש הנוכחי בשיטס');
const ranges=tabs.map(x=>"'"+x+"'!A1:I");while(ranges.length<4)ranges.push(ranges[0]||"A1:A1");
const late=now.getHours()>=16;
if(sameDay){errors.length=0;errors.push('SAMEDAY');}
if(late){errors.length=0;errors.push('LATE');}
const F=fmt(ds.d,null);
const help=late?'⏰ אחרי השעה 16:00 אי אפשר לשלוח בקשת הקדמה דרך הבוט.\nאם רוצים להקדים את הלקוח - תדבר/י עם קורל.':sameDay?'הקדמה להיום לא עוברת במייל. זה תהליך בוואטסאפ מול איש הקשר משווקים יס (050-2552817): שולחים להם הקדמת לקוח חדש, ואחרי ההסבר שלהם שולחים הודעה אחת עם: מספר לקוח, כתובת, כמות ממירים, התקנת סיב (כן/לא), סיב קיים (כן/לא/לא רלוונטי), חלון זמן מועדף, ושם הנציג השולח.':'❗ '+errors.join('\n❗ ')+'\n\nכתוב/י למשל:\nהקדמה 3109013 ליום ראשון, לא משנה השעה\nאו: הקדמה 054-1234567 ל-1/10 10-12\n(אפשר מספר לקוח, טלפון, ת"ז או שם לקוח)';
return {ok:errors.length===0,rep:repName,slot:slotText,short_slot:shortSlot,email_text:'הלקוח מבקש הקדמה לתאריך '+(F.short_date||'')+' '+(emailSlot||'')+(String(input.fullname||'').trim()?'\nשם הלקוח: '+String(input.fullname).trim():'')+(String(input.city||'').trim()?'\nעיר: '+String(input.city).trim():''),help,errors:errors.join('\n'),phone,num,name,slot_start:ds.slot,
  ...F,r1:ranges[0],r2:ranges[1],r3:ranges[2],r4:ranges[3]};

const P=input.parsed||{};
const vr=(input.valueRanges||[]).map(x=>x.valueRange||x);
const tabOf=s=>String(s||'').replace(/!.*$/,'').replace(/^'|'$/g,'');
const order=[P.r1,P.r2,P.r3,P.r4].map(tabOf);
vr.sort((a,b)=>order.indexOf(tabOf(a.range))-order.indexOf(tabOf(b.range)));
const digits=s=>String(s||'').replace(/\D/g,'');
const norm=s=>String(s||'').replace(/[\s‏‎]+/g,' ').trim();
const seen=new Set();const found=[];
const doneTabs=new Set();
for(const r of vr){
  if(doneTabs.has(r.range))continue;doneTabs.add(r.range);
  const tab=tabOf(r.range);
  const rows=r.values||[];
  for(let i=1;i<rows.length;i++){
    const row=rows[i];const C=norm(row[2]),D=digits(row[3]),G=digits(row[6]),I=digits(row[8]).replace(/^0+/,'');
    let ok=false;
    if(P.phone) ok=D.length>=9&&D.slice(-9).endsWith(P.phone.slice(-9))||D.slice(-8)===P.phone.slice(-8);
    else if(P.num) ok=(G&&G===P.num)||(I&&I===P.num);
    else if(P.name){const ws=norm(P.name).split(' ');ok=C&&ws.every(w=>C.includes(w));}
    if(!ok)continue;
    const key=G||(C+D);if(seen.has(key))continue;seen.add(key);
    found.push({tab,row:i+1,name:C,phone:row[3]||'',old_date:row[4]||'',old_slot:row[5]||'',customer_number:G});
  }
}
// RULE (15/11/2026): current month first + duplicate rows of the same customer (same phone) collapse to the row that has a customer number. Do not remove.
{
  const cur=order[0];
  const best=new Map();
  for(const f of found){
    const k=digits(f.phone).slice(-9)||norm(f.name);
    const b=best.get(k);
    const score=x=>(x.customer_number?4:0)+(x.tab===cur?2:0)+(String(x.old_date||'').trim()?1:0);
    if(!b||score(f)>score(b)) best.set(k,f);
  }
  found.length=0; for(const f of best.values()) found.push(f);
}
let status,reply,rec=found[0]||{};
if(!found.length){status='notfound';reply='❎ הלקוח ('+(P.phone?'טלפון '+P.phone:P.num?'מספר '+P.num:'שם '+P.name)+') עוד לא בדוח מכר, אז אי אפשר לשלוח הקדמה.\nקודם צריך להוסיף את העסקה לדוח של קורל, ואחרי זה שולחים הקדמה. (אם העסקה כבר בדוח – בדוק/י שהמספר נכון.)';}
else if(found.length>1){status='multiple';reply='🔎 מצאתי כמה לקוחות מתאימים:\n'+found.slice(0,5).map(f=>'• '+f.name+' | '+f.phone+' | התקנה: '+f.old_date+' '+f.old_slot).join('\n')+'\n\nשלח/י שוב עם מספר הטלפון של הלקוח.';}
else if(!rec.customer_number){status='nonumber';reply='⚠️ מצאתי את '+rec.name+' אבל אין לו מספר לקוח בשיטס (עמודה G), אז אי אפשר לשלוח מייל. תעדכן/י מספר לקוח ונסה/י שוב.';}
else{status='ok';reply='✅ קיבלתי! נשלחה בקשת הקדמה:\n👤 '+rec.name+' (לקוח '+rec.customer_number+')\n📅 '+P.full_date+'\n🕐 '+P.slot+'\n\nאעדכן אותך ברגע שתגיע תשובה מהחברה.';}
return {status,reply,...rec};

